import { useState } from 'react';
import { KeyboardSensor, PointerSensor, useSensor, useSensors } from '@dnd-kit/core';
import CareerListHeader from './CareerListHeader';
import KanbanBoard from './KanbanBoard';
import CustomerDetailsDialog from './CustomerDetailsDialog';
import TypeChangeDialog from './TypeChangeDialog';
import { useSalesList } from './useSalesList';

export default function CarerListComponent() {
    const [searchQuery, setSearchQuery] = useState('');

    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: {
                distance: 8,
            },
        }),
        useSensor(KeyboardSensor),
    );

    const {
        salesStages,
        isLoading,
        activeId,
        selectedCustomerId,
        customerDetails,
        isLoadingDetails,
        typeTracks,
        isLoadingTypeTracks,
        isTypeChangeDialogOpen,
        pendingTypeChange,
        isSubmittingTypeChange,
        handleDragStart,
        handleDragEnd,
        handleCardClick,
        handleCloseDialog,
        handleTypeChangeSubmit,
        handleCloseTypeChangeDialog,
        setIsTypeChangeDialogOpen,
        setPendingTypeChange,
    } = useSalesList(searchQuery);

    if (isLoading) {
        return (
            <div className="w-full bg-gray-100/45 p-6 rounded-lg mt-6">
                <div className="flex items-center justify-center h-64">
                    <p className="text-gray-600 font-cairo">جاري التحميل...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="w-full bg-gray-100/45 p-6 rounded-lg mt-6">
            <CareerListHeader searchQuery={searchQuery} onSearchChange={setSearchQuery} />
            <KanbanBoard
                salesStages={salesStages}
                activeId={activeId}
                sensors={sensors}
                onDragStart={handleDragStart}
                onDragEnd={handleDragEnd}
                onCardClick={handleCardClick}
            />
            {/* <CustomerDetailsDialog
                isOpen={selectedCustomerId !== null}
                customer={customerDetails}
                isLoading={isLoadingDetails}
                typeTracks={typeTracks}
                isLoadingTypeTracks={isLoadingTypeTracks}
                onClose={handleCloseDialog}
            /> */}
            <CustomerDetailsDialog
                isOpen={selectedCustomerId !== null}
                customer={customerDetails}
                isLoading={isLoadingDetails}
                typeTracks={typeTracks}
                isLoadingTypeTracks={isLoadingTypeTracks}
                onClose={handleCloseDialog}
                onOpenTypeChange={() => {
                    if (customerDetails && selectedCustomerId) {
                        setPendingTypeChange({
                            customerId: selectedCustomerId,
                            targetStage:
                                salesStages.find((s) => s.type === customerDetails.type) ||
                                salesStages[0],
                            dealId: selectedCustomerId.toString(),
                        });
                        setIsTypeChangeDialogOpen(true);
                    }
                }}
            />


            <TypeChangeDialog
                isOpen={isTypeChangeDialogOpen}
                targetStage={pendingTypeChange?.targetStage || null}
                onClose={handleCloseTypeChangeDialog}
                onSubmit={handleTypeChangeSubmit}
                isLoading={isSubmittingTypeChange}
            />
        </div>
    );
}
