import React, { useEffect, useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { LoadingSpinner } from '@/components/Loading/LoadingSpinner';
import { formatDateToArabic, formatCurrency } from './utils';
import { CustomerDetailsDialogProps } from '../../types/configs.types';
interface QuillContentProps {
    content: string;
}

// Inject styles once globally
const quillStylesInjected = { current: false };

function injectQuillStyles() {
    if (quillStylesInjected.current) return;

    const styleId = 'quill-content-styles';
    if (document.getElementById(styleId)) {
        quillStylesInjected.current = true;
        return;
    }

    const style = document.createElement('style');
    style.id = styleId;
    style.textContent = `
        .quill-content {
            direction: auto;
        }
        .quill-content p {
            margin: 0.5em 0;
            line-height: 1.6;
        }
        .quill-content p:first-child {
            margin-top: 0;
        }
        .quill-content p:last-child {
            margin-bottom: 0;
        }
        .quill-content h1,
        .quill-content h2,
        .quill-content h3 {
            font-weight: bold;
            margin: 1em 0 0.5em 0;
        }
        .quill-content h1 {
            font-size: 1.5em;
        }
        .quill-content h2 {
            font-size: 1.3em;
        }
        .quill-content h3 {
            font-size: 1.1em;
        }
        .quill-content ul,
        .quill-content ol {
            margin: 0.5em 0;
            padding-right: 1.5em;
            padding-left: 1.5em;
            direction: auto;
            list-style-position: outside !important;
        }
        .quill-content ul {
            list-style-type: disc !important;
        }
        .quill-content ol {
            list-style-type: decimal !important;
        }
        .quill-content li {
            margin: 0.25em 0;
            direction: auto;
            unicode-bidi: plaintext;
            display: list-item !important;
            list-style: inherit !important;
        }
        .quill-content li[dir="rtl"] {
            direction: rtl !important;
            text-align: right !important;
        }
        .quill-content li[dir="ltr"] {
            direction: ltr !important;
            text-align: left !important;
        }
        .quill-content a {
            color: #3b82f6;
            text-decoration: underline;
            word-break: break-all;
        }
        .quill-content a:hover {
            color: #2563eb;
        }
        .quill-content a:visited {
            color: #7c3aed;
        }
        .quill-content strong {
            font-weight: bold;
        }
        .quill-content em {
            font-style: italic;
        }
        .quill-content u {
            text-decoration: underline;
        }
        .quill-content s {
            text-decoration: line-through;
        }
        .quill-content blockquote {
            border-right: 4px solid #e5e7eb;
            padding-right: 1em;
            margin: 1em 0;
            font-style: italic;
            color: #6b7280;
        }
    `;
    document.head.appendChild(style);
    quillStylesInjected.current = true;
}

function QuillContent({ content }: QuillContentProps) {
    const contentRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        // Inject styles once
        injectQuillStyles();

        if (contentRef.current) {
            // Update list item directions based on content
            const listItems = contentRef.current.querySelectorAll('li');
            listItems.forEach((li) => {
                const text = li.textContent || '';
                const hasArabic = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/.test(text);

                if (hasArabic) {
                    li.setAttribute('dir', 'rtl');
                    (li as HTMLElement).style.direction = 'rtl';
                    (li as HTMLElement).style.textAlign = 'right';
                } else if (text.trim()) {
                    li.setAttribute('dir', 'ltr');
                    (li as HTMLElement).style.direction = 'ltr';
                    (li as HTMLElement).style.textAlign = 'left';
                }
            });
        }
    }, [content]);

    return (
        <div
            ref={contentRef}
            className="quill-content text-sm text-gray-700 font-cairo"
            dangerouslySetInnerHTML={{ __html: content }}
        />
    );
}

// interface CustomerDetailsDialogProps {
//     isOpen: boolean;
//     customer: Customer | null;
