export default function CustomerDetailsDialog({
    isOpen,
    customer,
    isLoading,
    typeTracks,
    isLoadingTypeTracks,
    onClose,
    onOpenTypeChange,
}: CustomerDetailsDialogProps) {
    const getCreatedByLabel = (
        createdBy: string | { id: number; name?: string; email?: string } | null | undefined,
    ) => {
        if (!createdBy) return 'غير محدد';
        if (typeof createdBy === 'string') return createdBy;
        if (typeof createdBy === 'object' && createdBy !== null) {
            return createdBy.name || createdBy.email || 'غير محدد';
        }
        return 'غير محدد';
    };

    const getTypeLabel = (type?: string) => {
        switch (type) {
            case 'in_progress':
                return 'تقديم';
            case 'qualified':
                return 'مقابلة ادارة الموارد البشرية';
            case 'contact':
                return 'مقابلة تقنية';
            case 'completed':
                return 'موظف';
          
            case 'failed':
                return 'مرفوض';
            default:
                return 'غير محدد';
        }
    };

    const getStatusLabel = (status?: string) => {
        switch (status) {
            case 'blocked':
                return 'محظور';
            case 'new':
                return 'جديد';
            default:
                return status || 'غير محدد';
        }
    };

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent
                className="lg:max-w-3xl max-w-2xl max-h-[90vh] overflow-y-auto left-0 right-0 mx-auto translate-x-0 "
                showCloseButton
            >
                <DialogHeader className="pb-4 border-b border-gray-200">
                    <DialogTitle className="md:text-2xl text-xl font-bold bg-gradient-to-r from-primery-blue-600 to-blue-800 bg-clip-text text-transparent font-cairo text-start">
                        تفاصيل العميل
                    </DialogTitle>
                </DialogHeader>
                {isLoading ? (
                    <div className="flex items-center justify-center py-20">
                        <LoadingSpinner />
                    </div>
                ) : customer ? (
                    <div className="space-y-8 mt-6">
                        {/* Basic Information */}
                        <div className="relative">
                            <div className="absolute inset-0 bg-gradient-to-r from-primery-blue-50 to-blue-50 rounded-2xl blur-sm opacity-30"></div>
                            <div className="relative bg-white border-2 border-gray-100 rounded-2xl p-6 shadow-sm">
                                <div className="flex items-center gap-3 mb-6 pb-4 border-b border-gray-100">
                                    <div className="w-1 h-8 bg-gradient-to-b from-primery-blue-500 to-blue-600 rounded-full"></div>
                                    <h3 className="md:text-xl text-lg font-bold text-gray-800 font-cairo">
                                        البيانات الأساسية
                                    </h3>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            الاسم الكامل
                                        </span>
                                        <p className="text-base font-semibold text-gray-800 font-cairo">
                                            {customer.full_name || `${customer.first_name} ${customer.last_name}`}
                                        </p>
                                    </div>
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            رقم الهاتف
                                        </span>
                                        <p className="text-base font-semibold text-gray-800 font-cairo">
                                            {customer.phone}
                                        </p>
                                    </div>
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            البريد الإلكتروني
                                        </span>
                                        <p className="text-base font-semibold text-gray-800 font-cairo">
                                            {customer.email || 'غير محدد'}
                                        </p>
                                    </div>
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            رقم الهوية
                                        </span>
                                        <p className="text-base font-semibold text-gray-800 font-cairo">
                                            {customer.national_id || 'غير محدد'}
                                        </p>
                                    </div>
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow md:col-span-2">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            العنوان
                                        </span>
                                        <p className="text-base font-semibold text-gray-800 font-cairo">
                                            {customer.address || 'غير محدد'}
                                        </p>
                                    </div>
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-primery-blue-50 to-blue-50 rounded-xl border-2 border-primery-blue-200">
                                        <span className="text-xs font-semibold text-primery-blue-700 font-cairo mb-2 uppercase tracking-wide">
                                            النوع
                                        </span>
                                        <p className="text-base font-bold text-primery-blue-900 font-cairo">
                                            {getTypeLabel(customer.type)}
                                        </p>
                                    </div>
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            تاريخ الإنشاء
                                        </span>
                                        <p className="text-base font-semibold text-gray-800 font-cairo">
                                            {formatDateToArabic(customer.created_at)}
                                        </p>
                                    </div>
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            أنشأ بواسطة
                                        </span>
                                        <p className="text-base font-semibold text-gray-800 font-cairo">
                                            {getCreatedByLabel(customer.created_by)}
                                        </p>
                                    </div>
                                    {customer.contact_period && (
                                        <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                            <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                                فترة الاتصال
                                            </span>
                                            <p className="text-base font-semibold text-gray-800 font-cairo">
                                                {customer.contact_period} يوم
                                            </p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Orders Information */}
                        <div className="relative">
                            <div className="absolute inset-0 bg-gradient-to-r from-green-50 to-emerald-50 rounded-2xl blur-sm opacity-30"></div>
                            <div className="relative bg-white border-2 border-gray-100 rounded-2xl p-6 shadow-sm">
                                <div className="flex items-center gap-3 mb-6 pb-4 border-b border-gray-100">
                                    <div className="w-1 h-8 bg-gradient-to-b from-green-500 to-emerald-600 rounded-full"></div>
                                    <h3 className="text-xl font-bold text-gray-800 font-cairo">الطلبات</h3>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-green-50 to-emerald-50 rounded-xl border-2 border-green-200">
                                        <span className="text-xs font-semibold text-green-700 font-cairo mb-2 uppercase tracking-wide">
                                            عدد الطلبات
                                        </span>
                                        <p className="text-2xl font-bold text-green-900 font-cairo">
                                            {customer.orders_count || 0}
                                        </p>
                                    </div>
                                    {customer.orders && customer.orders.length > 0 && (
                                        <div className="flex flex-col md:col-span-2">
                                            <span className="text-xs font-semibold text-gray-500 font-cairo mb-3 uppercase tracking-wide">
                                                تفاصيل الطلبات
                                            </span>
                                            <div className="space-y-2">
                                                {customer.orders.map((order: any, index: number) => (
                                                    <div
                                                        key={index}
                                                        className="p-4 bg-gradient-to-r from-gray-50 to-white rounded-xl border border-gray-200 hover:shadow-md transition-all"
                                                    >
                                                        <p className="text-sm font-semibold text-gray-700 font-cairo">
                                                            طلب #{order.id || index + 1}
                                                            {order.total && (
                                                                <span className="mr-2 text-green-600 font-bold">
                                                                    - {formatCurrency(order.total)}
                                                                </span>
                                                            )}
                                                        </p>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Status Information */}
                        <div className="relative">
                            <div className="absolute inset-0 bg-gradient-to-r from-purple-50 to-pink-50 rounded-2xl blur-sm opacity-30"></div>
                            <div className="relative bg-white border-2 border-gray-100 rounded-2xl p-6 shadow-sm">
                                <div className="flex items-center gap-3 mb-6 pb-4 border-b border-gray-100">
                                    <div className="w-1 h-8 bg-gradient-to-b from-purple-500 to-pink-600 rounded-full"></div>
                                    <h3 className="text-xl font-bold text-gray-800 font-cairo">الحالة</h3>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            الحالة
                                        </span>
                                        <p className="text-base font-semibold text-gray-800 font-cairo">
                                            {getStatusLabel(customer.status)}
                                        </p>
                                    </div>
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            في القائمة السوداء
                                        </span>
                                        <p
                                            className={`text-base font-bold font-cairo ${customer.is_black_list ? 'text-red-600' : 'text-green-600'}`}
                                        >
                                            {customer.is_black_list ? 'نعم' : 'لا'}
                                        </p>
                                    </div>
                                    <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                        <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                            نشط
                                        </span>
                                        <p
                                            className={`text-base font-bold font-cairo ${customer.is_active ? 'text-green-600' : 'text-gray-400'}`}
                                        >
                                            {customer.is_active ? 'نعم' : 'لا'}
                                        </p>
                                    </div>
                                    {customer.from && (
                                        <div className="flex flex-col p-4 bg-gradient-to-br from-gray-50 to-white rounded-xl border border-gray-100 hover:shadow-md transition-shadow">
                                            <span className="text-xs font-semibold text-gray-500 font-cairo mb-2 uppercase tracking-wide">
                                                المصدر
                                            </span>
                                            <p className="text-base font-semibold text-gray-800 font-cairo">
                                                {customer.from}
                                            </p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Type Tracks History */}
                        <div className="relative">
                            <div className="absolute inset-0 bg-gradient-to-r from-orange-50 to-amber-50 rounded-2xl blur-sm opacity-30"></div>
                            <div className="relative bg-white border-2 border-gray-100 rounded-2xl p-6 shadow-sm">
                                <div className="flex justify-between mb-6 pb-4 border-b border-gray-100">
                                    <div className="flex items-center gap-3 ">
                                        <div className="w-1 h-8 bg-gradient-to-b from-orange-500 to-amber-600 rounded-full"></div>
                                        <h3 className="text-xl font-bold text-gray-800 font-cairo">
                                            تتبع حركات العميل
                                        </h3>
                                    </div>
                                    <button
                                        className="px-4 py-2 bg-blue-300 text-white rounded-lg"
                                        onClick={onOpenTypeChange}
                                    >
                                        open
                                    </button>
                                </div>
                                {isLoadingTypeTracks ? (
                                    <div className="flex items-center justify-center py-12">
                                        <LoadingSpinner />
                                    </div>
                                ) : typeTracks.length > 0 ? (
                                    <div className="space-y-4">
                                        {typeTracks.map((track, index) => (
                                            <div key={track.id} className="relative group">
                                                <div className="absolute -inset-0.5 bg-gradient-to-rrounded-xl opacity-0 blur transition duration-300"></div>
                                                <div className="relative bg-gradient-to-br from-white to-gray-50 border-2 border-gray-200 rounded-xl p-5 hover:shadow-lg transition-all duration-300">
                                                    {/* Track Header */}
                                                    <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3 mb-4 pb-4 border-b border-gray-100">
                                                        <div className="flex items-center gap-3">
                                                            <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-orange-500 to-amber-600 flex items-center justify-center text-white font-bold shadow-md">
                                                                {typeTracks.length - index}
                                                            </div>
                                                            <div>
                                                                <div className="flex items-center gap-2">
                                                                    <span className="text-xs font-semibold text-gray-500 font-cairo uppercase">
                                                                        النوع:
                                                                    </span>
                                                                    <span className="px-3 py-1 bg-gradient-to-r from-primery-blue-100 to-blue-100 text-primery-blue-800 rounded-lg text-sm font-bold">
                                                                        {getTypeLabel(track.type)}
                                                                    </span>
                                                                </div>
                                                            </div>
                                                        </div>
                                                        <div className="flex items-center gap-2 text-sm">
                                                            <span className="text-gray-500 font-cairo">📅</span>
                                                            <span className="text-gray-700 font-cairo font-semibold">
                                                                {formatDateToArabic(track.created_at)}
                                                            </span>
                                                        </div>
                                                    </div>

                                                    {/* Notes */}
                                                    {track.notes && (
                                                        <div className="mb-4 p-4 bg-white rounded-lg border border-gray-100 shadow-md">
                                                            <span className="text-xs font-semibold text-gray-600 font-cairo block mb-3 uppercase tracking-wide">
                                                                الملاحظات:
                                                            </span>
                                                            <QuillContent content={track.notes} />
                                                        </div>
                                                    )}

                                                    {/* Started At */}
                                                    {track.started_at && (
                                                        <div className="mb-4 flex items-center gap-2 p-3 bg-blue-50 rounded-lg border border-blue-100">
                                                            <span className="text-xs font-semibold text-blue-700 font-cairo">
                                                                📆 تاريخ البدء:
                                                            </span>
                                                            <span className="text-sm text-blue-900 font-cairo font-semibold">
                                                                {formatDateToArabic(track.started_at)}
                                                            </span>
                                                        </div>
                                                    )}

                                                    {/* Created By */}
                                                    {track.created_by && (
                                                        <div className="flex items-center gap-2 pt-3 border-t border-gray-100">
                                                            <span className="text-xs text-gray-400 font-cairo">👤</span>
                                                            <span className="text-xs text-gray-500 font-cairo">
                                                                بواسطة:{' '}
                                                                <span className="font-semibold">
                                                                    {getCreatedByLabel(track.created_by)}
                                                                </span>
                                                            </span>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="text-center py-12 text-gray-400 font-cairo bg-gray-50 rounded-xl border-2 border-dashed border-gray-200">
                                        <div className="text-4xl mb-2">📋</div>
                                        <p>لا توجد سجلات تغيير نوع متاحة</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="text-center py-20 text-gray-500 font-cairo">
                        <div className="text-6xl mb-4">😕</div>
                        <p className="text-lg">لا توجد تفاصيل متاحة</p>
                    </div>
                )}
            </DialogContent>
        </Dialog>
    );
}
