import { useState, useEffect, useCallback } from 'react';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';
import { DragStartEvent, DragEndEvent } from '@dnd-kit/core';
import { SalesStage } from '../../../types/configs.types';
import { salesStagesConfig } from './constants';
import { transformCustomerToDeal } from './utils';
import { Customer } from '@/types/customer.types';
import { CustomerTypeTrack } from '../../../types/configs.types';

export function useSalesList(searchQuery = '') {
    const [salesStages, setSalesStages] = useState<SalesStage[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [activeId, setActiveId] = useState<string | null>(null);
    const [customersMap, setCustomersMap] = useState<Map<number, Customer>>(new Map());
    const [selectedCustomerId, setSelectedCustomerId] = useState<number | null>(null);
    const [customerDetails, setCustomerDetails] = useState<Customer | null>(null);
    const [isLoadingDetails, setIsLoadingDetails] = useState(false);
    const [typeTracks, setTypeTracks] = useState<CustomerTypeTrack[]>([]);
    const [isLoadingTypeTracks, setIsLoadingTypeTracks] = useState(false);
    const [isTypeChangeDialogOpen, setIsTypeChangeDialogOpen] = useState(false);
    const [pendingTypeChange, setPendingTypeChange] = useState<{
        customerId: number;
        targetStage: SalesStage;
        dealId: string;
    } | null>(null);
    const [isSubmittingTypeChange, setIsSubmittingTypeChange] = useState(false);
    const [allSalesStages, setAllSalesStages] = useState<SalesStage[]>([]);

    const fetchCustomers = useCallback(async () => {
        setIsLoading(true);
        try {
            // Fetch all customers by fetching all pages
            let allCustomers: Customer[] = [];
            let currentPage = 1;
            let hasMorePages = true;

            while (hasMorePages) {
                const response = await apiGet({
                    endpoint: endpoints.career.list,
                    queryParams: {
                        page: currentPage,
                    },
                });

                const pageData: Customer[] = response.data?.data?.data || [];
                const pagination = response.data?.data?.pagination;

                allCustomers = [...allCustomers, ...pageData];

                // Check if there are more pages
                if (pagination) {
                    const totalPages = Math.ceil(pagination.total / (pagination.per_page || 10));
                    hasMorePages = currentPage < totalPages;
                } else {
                    // If no pagination info, stop after first page
                    hasMorePages = false;
                }

                currentPage++;

                // Safety limit to prevent infinite loops
                if (currentPage > 100) {
                    break;
                }
            }

            // Store customers map for quick lookup
            const customersMapData = new Map<number, Customer>();
            allCustomers.forEach((customer) => {
                customersMapData.set(customer.id, customer);
            });
            setCustomersMap(customersMapData);

            // Group customers by type
            const customersByType = allCustomers.reduce((acc, customer) => {
                const type = customer.type || 'in_progress';
                if (!acc[type]) {
                    acc[type] = [];
                }
                acc[type].push(customer);
                return acc;
            }, {} as Record<string, Customer[]>);

            // Transform to sales stages
            const stages: SalesStage[] = salesStagesConfig.map((stageConfig) => {
                const customersOfType = customersByType[stageConfig.type] || [];
                const deals = customersOfType.map(transformCustomerToDeal);

                return {
                    ...stageConfig,
                    count: customersOfType.length,
                    deals,
                };
            });

            setAllSalesStages(stages);
        } catch (error) {
            // Set empty stages on error
            const emptyStages = salesStagesConfig.map((stageConfig) => ({
                ...stageConfig,
                count: 0,
                deals: [],
            }));
            setAllSalesStages(emptyStages);
        } finally {
            setIsLoading(false);
        }
    }, []);

    // Filter sales stages based on search query
    useEffect(() => {
        if (!searchQuery.trim()) {
            setSalesStages(allSalesStages);
            return;
        }

        const query = searchQuery.toLowerCase().trim();
        const filteredStages = allSalesStages.map((stage) => {
            const filteredDeals = stage.deals.filter((deal) => {
                const name = deal.name?.toLowerCase() || '';
                return name.includes(query);
            });

            return {
                ...stage,
                deals: filteredDeals,
                count: filteredDeals.length,
            };
        });

        setSalesStages(filteredStages);
    }, [searchQuery, allSalesStages]);

    useEffect(() => {
        fetchCustomers();
    }, [fetchCustomers]);

    const handleDragStart = (event: DragStartEvent) => {
        setActiveId(event.active.id as string);
    };

    const handleCardClick = async (dealId: string) => {
        const customerId = parseInt(dealId);
        
        // Prevent fetching if already loading or if same customer is already selected
        if (selectedCustomerId === customerId && customerDetails && !isLoadingDetails) {
            return;
        }
        
        setSelectedCustomerId(customerId);
        setIsLoadingDetails(true);
        setIsLoadingTypeTracks(true);

        try {
            // Fetch customer details and type tracks in parallel
            const [customerResponse, typeTracksResponse] = await Promise.all([
                apiGet({
                    endpoint: `${endpoints.customer.show}${customerId}`,
                }),
                apiGet({
                    endpoint: `${endpoints.customer.typeTrack}${customerId}`,
                }),
            ]);
            setCustomerDetails(customerResponse.data.data);
            
            // Handle different response structures and remove duplicates
            const tracksData = typeTracksResponse.data?.data || typeTracksResponse.data || [];
            
            if (Array.isArray(tracksData) && tracksData.length > 0) {
                // Use Map to ensure unique tracks by id (keeps the last occurrence)
                const tracksMap = new Map<number, CustomerTypeTrack>();
                tracksData.forEach((track: CustomerTypeTrack) => {
                    if (track && track.id) {
                        tracksMap.set(track.id, track);
                    }
                });
                
                // Convert to array, sort by created_at (newest first), and ensure uniqueness
                const uniqueTracks = Array.from(tracksMap.values())
                    .sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())
                    .slice(0, 10); // عرض آخر 10 سجلات فقط
                
                setTypeTracks(uniqueTracks);
            } else {
                setTypeTracks([]);
            }
        } catch (error) {
            toast.error('حدث خطأ أثناء جلب تفاصيل العميل');
            setTypeTracks([]);
        } finally {
            setIsLoadingDetails(false);
            setIsLoadingTypeTracks(false);
        }
    };

    const handleCloseDialog = () => {
        setSelectedCustomerId(null);
        setCustomerDetails(null);
        setTypeTracks([]);
    };

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;
        setActiveId(null);

        if (!over) return;

        const dealId = active.id as string;
        const targetStageId = over.id as string;

        // Find the current stage and deal
        const currentStage = salesStages.find((stage) =>
            stage.deals.some((deal) => deal.id === dealId)
        );

        if (!currentStage) return;

        // Check if dropped in the same stage
        if (currentStage.id === targetStageId) return;

        // Find the target stage
        const targetStage = salesStages.find((stage) => stage.id === targetStageId);
        if (!targetStage) return;

        // Get customer from map
        const customerId = parseInt(dealId);
        const customer = customersMap.get(customerId);

        if (!customer) return;

        // Store pending change and show dialog
        setPendingTypeChange({
            customerId,
            targetStage,
            dealId,
        });
        setIsTypeChangeDialogOpen(true);
    };

    const handleTypeChangeSubmit = async (tracks: Array<{ type: string; notes: string; started_at?: string }>) => {
        if (!pendingTypeChange) return;

        setIsSubmittingTypeChange(true);

        try {
            const requestBody = {
                tracks: tracks.map(track => ({
                    type: track.type,
                    notes: track.notes || '',
                    ...(track.started_at && { started_at: track.started_at })
                }))
            };

            await apiPost({
                endpoint: `${endpoints.customer.typeTrack}${pendingTypeChange.customerId}`,
                body: requestBody,
            });

            toast.success('تم تحديث نوع العميل بنجاح');

            // Close dialog and reset pending change
            setIsTypeChangeDialogOpen(false);
            setPendingTypeChange(null);

            // Refresh data to ensure consistency
            setTimeout(() => {
                fetchCustomers();
            }, 500);
        } catch (error: any) {
            let errorMessage = 'حدث خطأ أثناء تحديث نوع العميل. يرجى المحاولة مرة أخرى.';
            if (error.response) {
                errorMessage = error.response.data.msg || errorMessage;
            } else if (error.request) {
                errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
            }
            toast.error(errorMessage);
        } finally {
            setIsSubmittingTypeChange(false);
        }
    };

    const handleCloseTypeChangeDialog = () => {
        setIsTypeChangeDialogOpen(false);
        setPendingTypeChange(null);
    };

    return {
        salesStages,
        isLoading,
        activeId,
        selectedCustomerId,
        customerDetails,
        isLoadingDetails,
        typeTracks,
        isLoadingTypeTracks,
        isTypeChangeDialogOpen,
        pendingTypeChange,
        isSubmittingTypeChange,
        handleDragStart,
        handleDragEnd,
        handleCardClick,
        handleCloseDialog,
        handleTypeChangeSubmit,
        handleCloseTypeChangeDialog,
        setIsTypeChangeDialogOpen,
        setPendingTypeChange
    };
}

