import { Formik, Field, FieldArray } from 'formik';
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { TypeChangeDialogProps, TrackFormValue } from '../../types/configs.types';
import TrashIcon from '@/components/icons/TrashIcon';
import { useRef, useEffect } from 'react';

const toolbarOptions = {
    toolbar: [
        [{ header: [1, 2, 3, false] }],
        ['bold', 'italic', 'underline', 'strike'],
        [{ list: 'ordered' }, { list: 'bullet' }],
        [{ color: [] }, { background: [] }],
        ['link'],
        ['clean'],
    ],
    clipboard: {
        matchVisual: false,
    },
};

interface QuillEditorProps {
    value: string;
    onChange: (content: string) => void;
}

function QuillEditor({ value, onChange }: QuillEditorProps) {
    const quillRef = useRef<ReactQuill>(null);

    useEffect(() => {
        if (quillRef.current) {
            const quill = quillRef.current.getEditor();
            const editorElement = quill.root as HTMLElement;

            // Set editor to support bidirectional text
            editorElement.setAttribute('dir', 'auto');
            editorElement.style.direction = 'auto';

            // Function to update list item directions
            const updateListDirections = () => {
                const listItems = editorElement.querySelectorAll('li');
                listItems.forEach((li) => {
                    const text = li.textContent || '';
                    const hasArabic = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/.test(text);

                    if (hasArabic) {
                        li.setAttribute('dir', 'rtl');
                        (li as HTMLElement).style.direction = 'rtl';
                        (li as HTMLElement).style.textAlign = 'right';
                    } else if (text.trim()) {
                        li.setAttribute('dir', 'ltr');
                        (li as HTMLElement).style.direction = 'ltr';
                        (li as HTMLElement).style.textAlign = 'left';
                    } else {
                        // Empty list item - keep auto direction
                        li.setAttribute('dir', 'auto');
                        (li as HTMLElement).style.direction = 'auto';
                    }
                });
            };

            // Use MutationObserver to update list item directions
            const observer = new MutationObserver(() => {
                // Use requestAnimationFrame to update after Quill has processed the change
                requestAnimationFrame(updateListDirections);
            });

            // Observe changes to the editor content
            observer.observe(editorElement, {
                childList: true,
                subtree: true,
                characterData: true,
            });

            // Also update on text changes (for immediate feedback)
            const handleTextChange = () => {
                requestAnimationFrame(updateListDirections);
            };

            quill.on('text-change', handleTextChange);
            quill.on('selection-change', () => {
                requestAnimationFrame(updateListDirections);
            });

            // Initial update
            updateListDirections();

            return () => {
                observer.disconnect();
                quill.off('text-change', handleTextChange);
            };
        }
    }, []);

    return (
        <>
            <div className="quill-wrapper">
                <ReactQuill
                    ref={quillRef}
                    theme="snow"
                    modules={toolbarOptions}
                    className="bg-white rounded border border-gray-300"
                    value={value}
                    onChange={onChange}
                    formats={[
                        'header',
                        'bold',
                        'italic',
                        'underline',
                        'strike',
                        'list',
                        'bullet',
                        'color',
                        'background',
                        'link',
                    ]}
                />
            </div>
            <style>{`
                .quill-wrapper .ql-editor {
                    min-height: 200px;
                    direction: auto;
                }
                .quill-wrapper .ql-editor ol,
                .quill-wrapper .ql-editor ul {
                    padding-left: 1.5em;
                    padding-right: 1.5em;
                    direction: auto;
                }
                .quill-wrapper .ql-editor li {
                    unicode-bidi: plaintext;
                    direction: auto;
                    text-align: start;
                    white-space: pre-wrap;
                    word-wrap: break-word;
                }
                .quill-wrapper .ql-editor li[dir="rtl"] {
                    direction: rtl !important;
                    text-align: right !important;
                }
                .quill-wrapper .ql-editor li[dir="ltr"] {
                    direction: ltr !important;
                    text-align: left !important;
                }
                /* Ensure input works properly in lists */
                .quill-wrapper .ql-editor li.ql-indent-1,
                .quill-wrapper .ql-editor li.ql-indent-2,
                .quill-wrapper .ql-editor li.ql-indent-3,
                .quill-wrapper .ql-editor li.ql-indent-4,
                .quill-wrapper .ql-editor li.ql-indent-5,
                .quill-wrapper .ql-editor li.ql-indent-6,
                .quill-wrapper .ql-editor li.ql-indent-7,
                .quill-wrapper .ql-editor li.ql-indent-8 {
                    direction: auto;
                }
            `}</style>
        </>
    );
}



export default function TypeChangeDialog({
    isOpen,
    targetStage,
    onClose,
    onSubmit,
    isLoading = false,
}: TypeChangeDialogProps) {
    const handleClose = () => {
        onClose();
    };

    if (!targetStage) return null;

    return (
        <Dialog open={isOpen} onOpenChange={handleClose}>
            <DialogContent showCloseButton className="max-w-4xl">
                <DialogHeader className="pb-4 border-b border-gray-200">
                    <DialogTitle className="text-center font-bold text-2xl bg-gradient-to-r from-primery-blue-600 to-primery-blue-800 bg-clip-text text-transparent">
                        تغيير نوع العميل
                    </DialogTitle>
                </DialogHeader>

                <Formik
                    initialValues={{ tracks: [{ notes: '', started_at: '' }] }}
                    onSubmit={async (values) => {
                        const tracks = values.tracks.map((track) => {
                            let started_at = track.started_at;
                            // Convert datetime-local format (YYYY-MM-DDTHH:mm) to API format (YYYY-MM-DD HH:mm:ss)
                            if (started_at) {
                                const date = new Date(started_at);
                                if (!isNaN(date.getTime())) {
                                    const year = date.getFullYear();
                                    const month = String(date.getMonth() + 1).padStart(2, '0');
                                    const day = String(date.getDate()).padStart(2, '0');
                                    const hours = String(date.getHours()).padStart(2, '0');
                                    const minutes = String(date.getMinutes()).padStart(2, '0');
                                    started_at = `${year}-${month}-${day} ${hours}:${minutes}:00`;
                                }
                            }
                            return {
                                type: targetStage.type, // Set type automatically from targetStage
                                notes: track.notes || '',
                                ...(started_at && { started_at }),
                            };
                        });
                        await onSubmit(tracks);
                    }}
                >
                    {({ handleSubmit, isSubmitting, values }) => (
                        <form onSubmit={handleSubmit}>
                            <div className="space-y-6 py-6 max-h-[65vh] overflow-y-auto px-1">
                                {/* New Type Badge */}
                                <div className="relative">
                                    <div className="absolute inset-0 bg-gradient-to-r from-primery-blue-50 to-blue-50 rounded-xl blur-sm opacity-50"></div>
                                    <div className="relative bg-gradient-to-r from-primery-blue-50 to-blue-50 border-2 border-primery-blue-200 rounded-xl p-4">
                                        {/* <label className="block text-xs font-semibold text-primery-blue-700 mb-2 uppercase tracking-wide">
                                            النوع الجديد
                                        </label> */}
                                        <div className="flex items-center gap-3">
                                            <div className="w-2 h-2 rounded-full bg-primery-blue-500 animate-pulse"></div>
                                            <span className="text-lg font-bold text-primery-blue-900">
                                                {targetStage.name}
                                            </span>
                                        </div>
                                    </div>
                                </div>

                                <FieldArray name="tracks">
                                    {({ push, remove }) => (
                                        <div className="space-y-5">
                                            {values?.tracks?.map((track: TrackFormValue, index: number) => (
                                                <div
                                                    key={index}
                                                    className="relative group"
                                                >
                                                    <div className="absolute -inset-0.5 bg-gradient-to-r  rounded-2xl opacity-0 blur transition duration-300"></div>
                                                    <div className="relative bg-white border-2 border-gray-200 rounded-2xl p-6 shadow-sm hover:shadow-md transition-all duration-300">
                                                        {/* Track Header */}
                                                        <div className="flex items-center justify-between mb-5 pb-4 border-b border-gray-100">
                                                            <div className="flex items-center gap-3">
                                                                <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-primery-blue-500 to-blue-600 flex items-center justify-center text-white font-bold text-lg shadow-md">
                                                                    {index + 1}
                                                                </div>
                                                                <div>

                                                                    <h4 className="text-base font-semibold text-gray-800">
                                                                        {/* مسار {index + 1} */}
                                                                    </h4>
                                                                    <p className="text-xs text-gray-500">أضف الملاحظات والتاريخ</p>
                                                                </div>
                                                            </div>
                                                            {values.tracks.length > 1 && (
                                                                <button
                                                                    type="button"
                                                                    onClick={() => remove(index)}
                                                                    className="p-2 rounded-lg text-red-500 hover:bg-red-50 hover:text-red-700 transition-colors duration-200"
                                                                    title="حذف المسار"
                                                                >
                                                                    <TrashIcon className="w-5 h-5" />
                                                                </button>
                                                            )}
                                                        </div>

                                                        {/* Notes Section */}
                                                        <div className="mb-5">
                                                            <label className="text-sm font-semibold text-gray-700 mb-3 flex items-center gap-2">
                                                                <span className="w-1 h-4 bg-gradient-to-b from-primery-blue-500 to-blue-600 rounded-full"></span>
                                                                الملاحظات
                                                            </label>
                                                            <Field name={`tracks.${index}.notes`}>
                                                                {({ field, form, meta }: any) => (
                                                                    <div className="relative">
                                                                        <div className="border-2 border-gray-200 rounded-xl overflow-hidden hover:border-primery-blue-300 transition-colors">
                                                                            <QuillEditor
                                                                                value={field.value || ''}
                                                                                onChange={(content) =>
                                                                                    form.setFieldValue(field.name, content)
                                                                                }
                                                                            />
                                                                        </div>
                                                                        {meta.touched && meta.error && (
                                                                            <div className="mt-2 text-red-500 text-sm flex items-center gap-1">
                                                                                <span>⚠</span>
                                                                                {meta.error}
                                                                            </div>
                                                                        )}
                                                                    </div>
                                                                )}
                                                            </Field>
                                                        </div>

                                                        {/* Date Section */}
                                                        <div>
                                                            <label className="text-sm font-semibold text-gray-700 mb-3 flex items-center gap-2">
                                                                <span className="w-1 h-4 bg-gradient-to-b from-primery-blue-500 to-blue-600 rounded-full"></span>
                                                                تاريخ البدء <span className="text-xs font-normal text-gray-400">(اختياري)</span>
                                                            </label>
                                                            <Field name={`tracks.${index}.started_at`}>
                                                                {({ field, meta }: any) => (
                                                                    <div>
                                                                        <input
                                                                            type="datetime-local"
                                                                            {...field}
                                                                            className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl text-primery-blue-900 bg-white focus:border-primery-blue-400 focus:ring-2 focus:ring-primery-blue-100 transition-all outline-none"
                                                                        />
                                                                        {meta.touched && meta.error && (
                                                                            <div className="mt-2 text-red-500 text-sm flex items-center gap-1">
                                                                                <span>⚠</span>
                                                                                {meta.error}
                                                                            </div>
                                                                        )}
                                                                    </div>
                                                                )}
                                                            </Field>
                                                        </div>
                                                    </div>
                                                </div>
                                            ))}

                                            {/* Add Track Button */}
                                            <button
                                                type="button"
                                                onClick={() => push({ notes: '', started_at: '' })}
                                                className="w-full py-4 px-6 border-2 border-dashed border-primery-blue-300 rounded-2xl text-primery-blue-700 hover:border-primery-blue-500 hover:bg-gradient-to-r hover:from-primery-blue-50 hover:to-blue-50 transition-all duration-300 font-semibold flex items-center justify-center gap-2 group"
                                            >
                                                <span className="text-xl group-hover:scale-110 transition-transform">+</span>
                                                <span>إضافة مسار جديد</span>
                                            </button>
                                        </div>
                                    )}
                                </FieldArray>
                            </div>

                            <DialogFooter className="flex flex-row gap-3 sm:justify-end pt-4 border-t border-gray-200 mt-4">
                                <SecondaryButton
                                    type="button"
                                    onClick={handleClose}
                                    disabled={isLoading || isSubmitting}
                                    className="w-full sm:w-auto px-6 py-2.5"
                                >
                                    إلغاء
                                </SecondaryButton>
                                <PrimaryButton
                                    type="submit"
                                    disabled={isLoading || isSubmitting}
                                    className="w-full sm:w-auto px-6 py-2.5 bg-gradient-to-r from-primery-blue-600 to-blue-600 hover:from-primery-blue-700 hover:to-blue-700 shadow-lg hover:shadow-xl transition-all"
                                >
                                    {isLoading || isSubmitting ? (
                                        <span className="flex items-center gap-2">
                                            <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></span>
                                            جاري الحفظ...
                                        </span>
                                    ) : (
                                        'حفظ'
                                    )}
                                </PrimaryButton>
                            </DialogFooter>
                        </form>
                    )}
                </Formik>
            </DialogContent>
        </Dialog>
    );
}
