import { Customer } from '@/types/customer.types';
import { Deal } from '../../types/configs.types';

export const formatCurrency = (value: number): string => {
    return `${value.toLocaleString('ar-EG')} ج.م`;
};

export const formatDateToArabic = (dateString: string): string => {
    const date = new Date(dateString);
    const year = date.getFullYear();
    const month = date.getMonth() + 1;
    const day = date.getDate();

    // Convert to Arabic-Indic numerals
    const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
    const convertToArabic = (num: number): string => {
        return num
            .toString()
            .split('')
            .map((digit) => arabicNumerals[parseInt(digit)])
            .join('');
    };

    return `${convertToArabic(year)}/${convertToArabic(month)}/${convertToArabic(day)}`;
};

export const getInitials = (name: string): string => {
    if (!name) return '';
    return name
        .split(' ')
        .map((word) => word[0])
        .join('')
        .toLowerCase()
        .substring(0, 1);
};

export const transformCustomerToDeal = (customer: Customer): Deal => {
    // Calculate total order value (assuming orders have a total or price field)
    const totalValue = customer.orders?.reduce((sum, order) => {
        return sum + (order.total || order.price || 0);
    }, 0) || 0;

    // Calculate probability based on orders_count or default
    const probability = customer.orders_count > 0 ? Math.min(95, customer.orders_count * 20) : 50;

    return {
        id: customer.id.toString(),
        name: customer.full_name || `${customer.first_name} ${customer.last_name}`,
        client: customer.email || '',
        phone: customer.phone || '',
        value: totalValue,
        probability,
        expectedCloseDate: formatDateToArabic(customer.created_at),
        salesRep: customer.created_by || 'غير محدد',
        salesRepInitial: getInitials(customer.created_by || ''),
    };
};

